export const NOTES = [
  { title: 'Why alkyl halides react (7.1)', points: [
    'The halogen is electron-withdrawing: the α carbon is δ+ and gets attacked by nucleophiles.',
    'The halogen is a leaving group. Good leaving groups are the conjugate bases of strong acids (weak bases): I⁻ > Br⁻ > Cl⁻ ≫ F⁻; sulfonates (OTs, OMs, OTf) are excellent.',
    'With a nucleophile → substitution; with a base → elimination. A reagent that is both makes the two pathways compete.',
    'Label carbons α (bears the LG), β, γ… and classify the halide as 1°, 2° or 3° by branching at α.',
  ] },
  { title: 'SN2 (7.3–7.4)', points: [
    'Substitution, nucleophilic, bimolecular: one concerted step, one transition state, rate = k[substrate][Nu].',
    'Backside attack: electrons flow from the nucleophile’s HOMO into the C–LG σ* (LUMO); the front side has a node. Result: inversion of configuration (Walden inversion).',
    'TS: Nu and LG partially bonded, the other three groups trigonal planar.',
    'Steric hindrance controls the rate: methyl > 1° > 2° ≫ 3° (too slow to measure). Branching at the β carbon also slows it — neopentyl bromide is 1° but very slow.',
    'Strong nucleophiles favor SN2. Anions > neutrals (same attacking atom); polarizable atoms (I⁻, HS⁻, RS⁻) are excellent; resonance-stabilized anions (acetate, phenoxide) and bulky ones (t-BuO⁻) are weaker.',
    'Polar aprotic solvents (DMSO, DMF, acetone, THF, CH₃CN) speed SN2: they don’t H-bond to the nucleophile, so it stays reactive (lower Ea).',
  ] },
  { title: 'E2 (7.5–7.7)', points: [
    'Strong base removes a β-H while the π bond forms and the LG leaves — concerted, rate = k[substrate][base].',
    'Alkene stability: more alkyl groups (hyperconjugation) = more stable; trans > cis (steric strain).',
    'Regioselective: unhindered bases (HO⁻, MeO⁻, EtO⁻, NaH) → Zaitsev (more substituted) major; bulky bases (t-BuOK, LDA) → Hofmann (less substituted) major.',
    'The β-H and LG must be anti-periplanar (~180°; the staggered anti rotamer is far lower in energy than the syn-coplanar eclipsed one).',
    'Stereospecific when the β carbon has only one H: the anti-periplanar conformation fixes E vs Z (it can even give the less stable Z). With two β-H’s it’s stereoselective (trans favored).',
    'Cyclohexanes: the LG must be axial with an axial β-H on the neighbouring carbon (trans-diaxial). A chair that puts the LG equatorial can’t do E2.',
    'Bredt’s rule: no C=C at the bridgehead of small bicyclic rings.',
  ] },
  { title: 'SN2 vs E2 (7.8)', points: [
    'Reagent that is both a strong nucleophile and a strong base (HO⁻, MeO⁻, EtO⁻): 1° → SN2 major (unless bulky base); 2° → E2 major; 3° → E2 only.',
    'Strong nucleophile, weak base (I⁻, Br⁻, Cl⁻, HS⁻, RS⁻, N₃⁻, CN⁻, RCOO⁻): SN2 only.',
    'Strong base, weak nucleophile (NaH, t-BuOK, LDA, DBU, DBN): E2 only.',
    'No β-H → no elimination, whatever the base.',
  ] },
  { title: 'SN1 and E1 (7.9)', points: [
    'Stepwise: ionization (rate-determining) → carbocation → nucleophile attacks (SN1) or a β-H is removed (E1). Rate = k[substrate] for both.',
    'Solvolysis: the solvent is the nucleophile/base (H₂O, ROH). With a neutral nucleophile, the last step is a proton transfer.',
    'Rate follows carbocation stability: 3°, allylic and benzylic (resonance) are practical; 1° and 2° only if they can rearrange. Better LG → faster ionization.',
    'Carbocations rearrange by 1,2-hydride or 1,2-methyl (methide) shifts, or ring expansion, when that gives a more stable cation.',
    'SN1 at a stereocenter gives both configurations — nearly racemic, with slightly more inversion because of the ion pair.',
    'E1 always favors the most stable (Zaitsev, trans) alkene; you can’t steer it with the base. Heat favors elimination.',
    'Polar protic solvents stabilize the carbocation → faster SN1.',
  ] },
  { title: 'Predicting the product (7.10)', points: [
    '1) Determine the function of the reagent (strong/weak nucleophile, strong/weak base, bulky?).',
    '2) Analyze the substrate (methyl, 1°, 2°, 3°; allylic/benzylic; β-H’s?) and decide the mechanism(s).',
    '3) Apply regio- and stereochemistry: SN2 = inversion; SN1 = both configurations, check rearrangement; E2 = anti-periplanar H’s only, Zaitsev vs Hofmann by base size; E1 = most stable alkene.',
  ] },
  { title: 'Alcohols and sulfonates (7.11)', points: [
    'OH is a bad leaving group; protonating it (HX, H₂SO₄) makes H₂O, a good one.',
    'TsCl/pyridine turns R–OH into R–OTs without touching the carbon (configuration kept) — then treat it like an alkyl halide.',
    'HX with alcohols: 1° → SN2; 2° and 3° → SN1 (watch for rearrangements).',
    'Conc. H₂SO₄ + heat → dehydration by E1 (2°, 3°), Zaitsev alkene major.',
  ] },
  { title: 'Synthesis and solvents (7.12–7.13)', points: [
    'Retrosynthesis: find a bond you know how to make, draw the substrate and nucleophile, check that the reaction is reasonable (avoid SN2 on 3° centers!), then write it forward.',
    'Ethers (Williamson): put the alkoxide on the bulky side and the leaving group on the less hindered carbon.',
    'For elimination targets, choose a substrate with one type of β-H, or pick the base size to get Zaitsev or Hofmann.',
    'SN2 → polar aprotic solvent; SN1 → polar protic solvent.',
  ] },
];

// ---------------------------------------------------------------- page

const KEY = 'orgo.prob.';
function readMark(id) { try { return localStorage.getItem(KEY + id) || ''; } catch { return ''; } }
function writeMark(id, v) { try { if (v) localStorage.setItem(KEY + id, v); else localStorage.removeItem(KEY + id); } catch {} }
function readPref(k, d) { try { return localStorage.getItem(KEY + '_' + k) || d; } catch { return d; } }
function writePref(k, v) { try { localStorage.setItem(KEY + '_' + k, v); } catch {} }

const ALL = PROBLEM_SETS.flatMap(s => s.problems.map(p => ({ ...p, set: s.id, setLabel: s.label })));
const shuffle = a => { const b = [...a]; for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [b[i], b[j]] = [b[j], b[i]]; } return b; };

const ps = {
  set: readPref('set', PROBLEM_SETS[PROBLEM_SETS.length - 1].id),
  i: 0, order: null, picked: null, revealed: false, opts: new Map(),
  right: 0, total: 0, notesOpen: false,
};

function listFor(set) {
  if (set === 'mixed') return ps.order || (ps.order = shuffle(ALL));
  if (set === 'missed') return ALL.filter(p => readMark(p.id) === 'missed');
  const s = PROBLEM_SETS.find(x => x.id === set) || PROBLEM_SETS[0];
  return ALL.filter(p => p.set === s.id);
}

function choicesFor(p) {
  if (!p.choices) return null;
  if (!ps.opts.has(p.id)) ps.opts.set(p.id, shuffle(p.choices.includes(p.answer) ? p.choices : [p.answer, ...p.choices]));
  return ps.opts.get(p.id);
}

export function problemsPage(C) {
  const { h, card } = C;
  const root = h('div', { class: 'grid orgo-grid prob-page' });

  const pickSet = id => { ps.set = id; ps.i = 0; ps.picked = null; ps.revealed = false; if (id === 'mixed') ps.order = shuffle(ALL); writePref('set', id); draw(); };
  const go = d => { ps.i += d; ps.picked = null; ps.revealed = false; draw(); };
  const mark = (p, v, counted) => {
    writeMark(p.id, v);
    if (counted) { ps.total++; if (v === 'got') ps.right++; }
    draw();
  };
  const chip = (label, on, onclick) => h('button', { type: 'button', class: `chip chip-btn${on ? ' on' : ''}`, 'aria-pressed': String(!!on), onclick }, label);

  function draw() {
    const list = listFor(ps.set);
    if (ps.i >= list.length) ps.i = Math.max(0, list.length - 1);
    const p = list[ps.i];
    const missedCount = ALL.filter(x => readMark(x.id) === 'missed').length;
    const gotCount = ALL.filter(x => readMark(x.id) === 'got').length;

    const picker = h('div', { class: 'prob-sets' },
      h('div', { class: 'chips' },
        PROBLEM_SETS.map(s => chip(s.label, ps.set === s.id, () => pickSet(s.id)))),
      h('div', { class: 'chips' },
        chip('Mixed review', ps.set === 'mixed', () => pickSet('mixed')),
        chip(`Missed ones · ${missedCount}`, ps.set === 'missed', () => pickSet('missed'))));

    let body;
    if (!p) {
      body = h('p', { class: 'empty', text: ps.set === 'missed' ? 'Nothing missed right now ✿' : 'No problems here.' });
    } else {
      const opts = choicesFor(p);
      const answered = opts ? ps.picked !== null : ps.revealed;
      const status = readMark(p.id);
      const setInfo = PROBLEM_SETS.find(s => s.id === p.set);
      body = h('div', { class: 'q-box prob-box' },
        h('div', { class: 'prob-meta' },
          h('span', { class: 'prob-topic', text: p.topic }),
          h('span', { class: 'muted small', text: `${ps.set === 'mixed' || ps.set === 'missed' ? `${p.setLabel} · ` : ''}${ps.i + 1} of ${list.length}` }),
          status ? h('span', { class: `prob-status ${status}`, text: status === 'got' ? 'Got it before' : 'Missed before' }) : null),
        h('p', { class: 'q-prompt prob-prompt', text: p.prompt }),
        opts
          ? h('div', { class: 'q-options' }, opts.map(o => {
            let cls = 'q-opt';
            if (answered && o === p.answer) cls += ' right';
            else if (answered && o === ps.picked) cls += ' wrong';
            return h('button', {
              type: 'button', class: cls, disabled: answered,
              onclick: () => { ps.picked = o; mark(p, o === p.answer ? 'got' : 'missed', true); },
            }, o);
          }))
          : (!answered ? h('button', { type: 'button', class: 'btn btn-primary prob-reveal', onclick: () => { ps.revealed = true; draw(); } }, 'Show answer') : null),
        answered ? h('div', { class: `q-feedback prob-feedback ${opts ? (ps.picked === p.answer ? 'ok' : 'no') : 'reveal'}` },
          opts ? h('strong', { text: ps.picked === p.answer ? 'Correct ✿' : `Not quite. Answer: ${p.answer}` })
            : h('div', null, h('strong', { text: 'Answer' }), h('p', { class: 'prob-answer', text: p.answer })),
          p.steps && p.steps.length ? h('ol', { class: 'bullets numbered prob-steps' }, p.steps.map(t => h('li', { text: t }))) : null,
          p.explain ? h('p', { class: 'prob-explain', text: p.explain }) : null,
          !opts ? h('div', { class: 'row prob-self' },
            h('span', { class: 'muted small', text: 'How did you do?' }),
            h('button', { type: 'button', class: `btn btn-small${status === 'got' ? ' btn-primary' : ''}`, onclick: () => mark(p, 'got', status === '') }, 'Got it'),
            h('button', { type: 'button', class: `btn btn-small${status === 'missed' ? ' btn-primary' : ''}`, onclick: () => mark(p, 'missed', status === '') }, 'Missed it')) : null) : null,
        h('div', { class: 'row prob-nav' },
          h('button', { type: 'button', class: 'btn btn-small', disabled: ps.i === 0, onclick: () => go(-1) }, '← Previous'),
          h('button', { type: 'button', class: 'btn btn-small btn-primary', disabled: ps.i >= list.length - 1, onclick: () => go(1) }, 'Next →')),
        setInfo && ps.set === p.set ? h('p', { class: 'muted small prob-topics', text: `Topics: ${setInfo.topics.join(' · ')}` }) : null);
    }

    const practice = card('Daily practice', h('span', { class: 'card-meta', text: ps.total ? `${ps.right} / ${ps.total} this session` : `${gotCount} of ${ALL.length} got` }),
      picker, body);

    const notes = h('section', { class: 'card prob-notes' },
      h('details', { open: ps.notesOpen ? '' : null, ontoggle: e => { ps.notesOpen = e.target.open; } },
        h('summary', null, h('h2', { text: 'Ch 7 notes' }), h('span', { class: 'card-meta', text: 'study guide' })),
        NOTES.map(n => h('div', { class: 'prob-note' },
          h('h3', { class: 'sub-h', text: n.title }),
          h('ul', { class: 'bullets' }, n.points.map(t => h('li', { text: t })))))));

    root.replaceChildren(h('div', { class: 'col' }, practice), h('div', { class: 'col col-narrow' }, notes));
  }

  draw();
  return root;
}
